<?php $success = sessionSuccess(); $error = sessionError(); ?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Room Assignments - DormSync</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f7f9fc;color:#172033;margin:0}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb;text-decoration:none}main{max-width:1100px;margin:auto;padding:36px 24px}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:22px;margin-bottom:20px}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #e7ebf2;padding:12px;text-align:left;font-size:13px}th{color:#718096;font-size:11px;text-transform:uppercase}.message{padding:10px;border-radius:6px;background:#dcfce7;color:#166534;margin-bottom:14px}.error{background:#fee2e2;color:#991b1b}select,button{padding:9px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}button{background:#2563eb;color:#fff;border-color:#2563eb;cursor:pointer}.danger{background:#fef2f2;color:#991b1b;border-color:#fecaca}@media(max-width:650px){.table-wrap{overflow:auto}table{min-width:700px}}</style></head><body><header class="topbar"><a href="/warden/dashboard">Back to dashboard</a></header><main><h1>Room assignments</h1><?php if($success):?><div class="message"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="message error"><?=htmlspecialchars($error)?></div><?php endif;?><section class="panel"><h2>Pending requests</h2><?php if($allocations):?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Student ID</th><th>Requested room</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($allocations as $allocation):?><tr><td><?=htmlspecialchars($allocation['full_name'])?></td><td><?=htmlspecialchars($allocation['student_id'])?></td><td><?=htmlspecialchars($allocation['room_number'])?></td><td><?=htmlspecialchars($allocation['request_date'])?></td><td><form method="post" action="/warden/allocation-action"><input type="hidden" name="allocation_id" value="<?= (int)$allocation['id'] ?>"><button name="action" value="approve">Approve</button> <button class="danger" name="action" value="reject">Reject</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No pending room assignments.</p><?php endif;?></section><section class="panel"><h2>Available rooms</h2><?php if($rooms):?><div class="table-wrap"><table><thead><tr><th>Room</th><th>Block</th><th>Capacity</th><th>Occupied</th></tr></thead><tbody><?php foreach($rooms as $room):?><tr><td><?=htmlspecialchars($room['room_number'])?></td><td><?=htmlspecialchars($room['block'])?></td><td><?= (int)$room['capacity']?></td><td><?= (int)$room['current_occupancy']?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No available rooms.</p><?php endif;?></section></main></body></html>
